46	export class ToolRegistry {
47	  private readonly tools = new Map<string, StoredTool>();
48	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
49	  private readonly ajv = new (Ajv as any)({strict: false, validateFormats: false});
50	  private readonly functionSchemaValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();
51	
52	  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
53	    return typeof source === 'function' ? source() : source;
54	  }
55	
56	  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
57	    const resolved = this.resolveDefinition(definition);
58	    let staticValidator: ValidateFunction | undefined;
59	    if (typeof definition !== 'function') {
60	      staticValidator = this.compileSchema(resolved.inputSchema, resolved.name);
61	    }
62	    this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator});
63	  }
64	
65	  private compileSchema(schema: Record<string, unknown>, toolName: string): ValidateFunction {
66	    try {
67	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
68	      return this.ajv.compile(schema) as any;
69	    } catch (error) {
70	      const err = new Error(`Failed to compile schema for tool "${toolName}": ${String(error)}`);
71	      err.cause = error;
72	      throw err;
73	    }
74	  }
75	
76	  private getOrCompileValidator(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
77	    if (tool.staticValidator) {
78	      return tool.staticValidator;
79	    }
80	
81	    const cached = this.functionSchemaValidators.get(definition.inputSchema);
82	    if (cached) {
83	      return cached;
84	    }
85	
86	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
87	    const compiled = this.ajv.compile(definition.inputSchema) as any;
88	    const validator = compiled as ValidateFunction;
89	    this.functionSchemaValidators.set(definition.inputSchema, validator);
90	    return validator;
91	  }
92	
93	  private formatValidationErrors(validator: ValidateFunction): string {
94	    const errors = validator.errors ?? [];
95	    const messages = errors.map((error: ErrorObject) => {
96	      const keyword = error.keyword;
97	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
98	      const params = error.params as any;
99	
100	      if (keyword === 'required' && params?.missingProperty) {
101	        return `Missing required property: ${params.missingProperty as string}`;
102	      }
103	
104	      if (keyword !== 'type' || !params?.type) {
105	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
106	        const path = (error as any).instancePath || '/';
107	        return `Validation failed at ${path}: ${keyword}`;
108	      }
109	
110	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
111	      const path = (error as any).instancePath || '';
112	      let propertyName: string | undefined;
113	
114	      if (path && path !== '/') {
115	        const parts = path.split('/').filter(Boolean);
116	        propertyName = parts[0];
117	      }
118	
119	      if (!propertyName) {
120	        const schemaPath = error.schemaPath;
121	        const parts = schemaPath.split('/');
122	        const propsIndex = parts.indexOf('properties');
123	        const canExtractProp = propsIndex >= 0 && propsIndex + 1 < parts.length;
124	        propertyName = canExtractProp ? parts[propsIndex + 1] : propertyName;
125	      }
126	
127	      propertyName = propertyName || 'value';
128	      return `Property ${propertyName} has wrong type (expected ${params.type as string})`;
129	    });
130	    return messages.join('; ');
131	  }
