134	    const tool = this.tools.get(name);
135	    if (!tool) return undefined;
136	    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
137	  }
138	
139	  getDefinitions(): ToolDefinition[] {
140	    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
141	  }
142	
143	  getPromptInstructions(): string[] {
144	    return this.getDefinitions()
145	      .filter(t => t.promptInstructions)
146	      .map(t => `${t.name}: ${t.promptInstructions}`);
147	  }
148	
149	  getExamplePrompts(): string[] {
150	    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
151	  }
152	
153	  has(name: string): boolean {
154	    return this.tools.has(name);
155	  }
156	
157	  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
158	    const tool = this.tools.get(name);
159	    if (!tool) {
160	      log.warn('tool', 'tool not found', {name});
161	      throw new Error(`Unknown tool: ${name}`);
162	    }
163	
164	    const definition = this.resolveDefinition(tool.definitionSource);
165	    const validator = this.getOrCompileValidator(tool, definition);
166	
167	    if (!validator(input)) {
168	      return {result: this.formatValidationErrors(validator)};
169	    }
170	
171	    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
172	    const rawResult = await tool.execute(input, context);
173	    const response = normalizeToolResponse(rawResult);
174	    log.info('tool', 'execution complete', {
175	      name,
176	      rawType: typeof rawResult,
177	      clientMessageCount: response.clientMessages?.length ?? 0,
178	      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
179	      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
180	    });
181	    return response;
182	  }
183	}
